package com.petlis.service.impl;
import com.petlis.common.exception.BusinessException;
import com.sun.net.httpserver.*;
import org.junit.jupiter.api.*;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import java.net.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.time.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
import static org.junit.jupiter.api.Assertions.*;
class LegacyBankGatewayClientTest {
 HttpServer server;ExecutorService executor;KeyPair merchant,gateway;AtomicInteger calls,redirected;AtomicReference<Throwable> failure;List<String> methods;
 @BeforeEach void setup()throws Exception{var g=KeyPairGenerator.getInstance("RSA");g.initialize(2048);merchant=g.generateKeyPair();gateway=g.generateKeyPair();methods=new CopyOnWriteArrayList<>();calls=new AtomicInteger();redirected=new AtomicInteger();failure=new AtomicReference<>();server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);executor=Executors.newCachedThreadPool();server.setExecutor(executor);
  server.createContext("/gateway",e->{calls.incrementAndGet();try{assertEquals("text/json;charset=utf-8",e.getRequestHeaders().getFirst("Content-Type"));String form=new String(e.getRequestBody().readAllBytes(),StandardCharsets.UTF_8);int marker=form.lastIndexOf("&sign=");String unsigned=form.substring(0,marker),hex=form.substring(marker+6);for(String pair:unsigned.split("&")){String[] part=pair.split("=",2);if(part[0].equals("method"))methods.add(URLDecoder.decode(part[1],StandardCharsets.UTF_8));if(part[0].equals("biz_content")){var business=new com.fasterxml.jackson.databind.ObjectMapper().readTree(URLDecoder.decode(part[1],StandardCharsets.UTF_8));var payload=business.path("msgBody");if(methods.get(methods.size()-1).endsWith(".prePay")){assertTrue(payload.path("trxTtlAmt").isTextual());assertEquals("1250",payload.path("trxTtlAmt").asText());}else{assertEquals("original-synthetic-order",payload.path("oriMerOrdrNo").asText());assertEquals("20261108123456",payload.path("oriTrxDt").asText());if(methods.get(methods.size()-1).endsWith(".refund")){assertTrue(payload.path("trxAmt").isIntegralNumber());assertEquals(1,payload.path("trxAmt").asInt());}}}}var verifier=Signature.getInstance("SHA256withRSA");verifier.initVerify(merchant.getPublic());verifier.update(unsigned.getBytes(StandardCharsets.UTF_8));assertTrue(verifier.verify(HexFormat.of().parseHex(hex)));respond(e,signed("{\"response\":{\"msgBody\":{\"retCode\":\"00000\",\"chnlUrl\":\"https://cashier.example.test/owned\"}}}"));}catch(Throwable error){failure.set(error);e.close();}});
  server.createContext("/bad",e->{calls.incrementAndGet();try{respond(e,"{\"response\":{\"msgBody\":{\"retCode\":\"00000\"}},\"sign\":\""+"00".repeat(256)+"\"}");}catch(Exception ex){e.close();}});
  server.createContext("/redirect",e->{calls.incrementAndGet();e.getResponseHeaders().add("Location","/followed");e.sendResponseHeaders(302,-1);e.close();});server.createContext("/followed",e->{redirected.incrementAndGet();e.sendResponseHeaders(500,-1);e.close();});
  server.createContext("/stall",e->{calls.incrementAndGet();try{e.sendResponseHeaders(200,0);e.getResponseBody().write('{');e.getResponseBody().flush();Thread.sleep(2000);}catch(Exception ignored){}finally{e.close();}});server.createContext("/large",e->{calls.incrementAndGet();try{e.sendResponseHeaders(200,0);e.getResponseBody().write(new byte[1024*1024+1]);e.getResponseBody().flush();Thread.sleep(2000);}catch(Exception ignored){}finally{e.close();}});server.start();
 }
 @AfterEach void cleanup(){server.stop(0);executor.shutdownNow();}
 LegacyBankGatewayClient client(String path,Duration timeout){return new LegacyBankGatewayClient(LegacyBankGatewayClient.Mode.TEST_LOCAL,URI.create("http://127.0.0.1:"+server.getAddress().getPort()+path),"test-app","test-merchant","https://callback.example.test/notify",merchant.getPrivate(),gateway.getPublic(),timeout);}
 LinkedHashMap<String,Object> parameters(){var p=new LinkedHashMap<String,Object>();p.put("merOrdrNo","synthetic-only");p.put("trxTtlAmt","1250");return p;}
 LinkedHashMap<String,Object> parameters(LegacyBankProtocol.Method method){var p=new LinkedHashMap<String,Object>();p.put("merOrdrNo","synthetic-only");if(method==LegacyBankProtocol.Method.PREPAY){p.put("trxTtlAmt","1250");p.put("bizType","14900");p.put("trxChnlType","01");p.put("subject","合成订单");p.put("ordrDesc","合成订单");p.put("userNo",7);p.put("userType","USER_ID");p.put("bizFunc","111011");}else{p.put("oriMerOrdrNo","original-synthetic-order");p.put("oriTrxDt","20261108123456");if(method==LegacyBankProtocol.Method.REFUND)p.put("trxAmt",1);}return p;}
 String signed(String raw)throws Exception{var s=Signature.getInstance("SHA256withRSA");s.initSign(gateway.getPrivate());s.update(raw.getBytes(StandardCharsets.UTF_8));return raw.substring(0,raw.length()-1)+",\"sign\":\""+HexFormat.of().formatHex(s.sign())+"\"}";}
 void respond(HttpExchange e,String body)throws Exception{byte[] bytes=body.getBytes(StandardCharsets.UTF_8);e.sendResponseHeaders(200,bytes.length);try(var out=e.getResponseBody()){out.write(bytes);}}
 @Test void sendsEachOriginalMethodOnceAndOnlyReturnsVerifiedBody(){var c=client("/gateway",Duration.ofSeconds(3));for(var method:LegacyBankProtocol.Method.values())assertEquals("https://cashier.example.test/owned",c.exchange(method,parameters(method)).path("chnlUrl").asText());assertNull(failure.get());assertEquals(4,calls.get());assertEquals(List.of("gnete.upbc.cashier.trade.prePay","gnete.upbc.cashier.trade.payQuery","gnete.upbc.cashier.trade.refund","gnete.upbc.cashier.trade.refundQuery"),methods);}
 @Test void disabledAndInvalidLocalEndpointsNeverConnect(){assertThrows(BusinessException.class,()->new LegacyBankGatewayClient().exchange(LegacyBankProtocol.Method.PREPAY,parameters()));assertThrows(BusinessException.class,()->new LegacyBankGatewayClient(LegacyBankGatewayClient.Mode.TEST_LOCAL,URI.create("http://localhost:1234/"),"a","m","c",merchant.getPrivate(),gateway.getPublic(),Duration.ofSeconds(1)));assertEquals(0,calls.get());}
 @Test void invalidSignatureAndRedirectBecomeUnknownWithoutAutomaticResend(){assertThrows(LegacyBankGatewayClient.UnknownResult.class,()->client("/bad",Duration.ofSeconds(3)).exchange(LegacyBankProtocol.Method.PREPAY,parameters()));assertThrows(LegacyBankGatewayClient.UnknownResult.class,()->client("/redirect",Duration.ofSeconds(3)).exchange(LegacyBankProtocol.Method.PREPAY,parameters()));assertEquals(2,calls.get());assertEquals(0,redirected.get());}
 @Test void timeoutCoversIncompleteResponseBodyAndDoesNotRetry(){var c=client("/stall",Duration.ofMillis(500));long start=System.nanoTime();assertThrows(LegacyBankGatewayClient.UnknownResult.class,()->c.exchange(LegacyBankProtocol.Method.PREPAY,parameters()));assertTrue(Duration.ofNanos(System.nanoTime()-start).toMillis()<1500);assertEquals(1,calls.get());}
 @Test void refusesNetworkInsideDatabaseTransaction(){TransactionSynchronizationManager.setActualTransactionActive(true);try{assertThrows(BusinessException.class,()->client("/gateway",Duration.ofSeconds(3)).exchange(LegacyBankProtocol.Method.PREPAY,parameters()));assertEquals(0,calls.get());}finally{TransactionSynchronizationManager.setActualTransactionActive(false);}}
 @Test void rejectsOversizedStreamingBodyWithoutWaitingForItsEnd(){var c=client("/large",Duration.ofSeconds(3));long start=System.nanoTime();assertThrows(LegacyBankGatewayClient.UnknownResult.class,()->c.exchange(LegacyBankProtocol.Method.PREPAY,parameters()));assertTrue(Duration.ofNanos(System.nanoTime()-start).toMillis()<1500);assertEquals(1,calls.get());}
 @Test void notificationVerifiesOriginalBytesWithoutNetworkAndRejectsDisabledOrTampered()throws Exception{
  String body=signed("{\"response\":{\"msgBody\":{\"tradeStatus\":\"00\",\"buyerLgnId\":\"notice-buyer\",\"trxTtlAmt\":\"1250\"}}}");var c=client("/gateway",Duration.ofSeconds(1));assertEquals("notice-buyer",c.verifyNotification(body.getBytes(StandardCharsets.UTF_8)).path("buyerLgnId").asText());assertThrows(BusinessException.class,()->c.verifyNotification(body.replace("1250","1251").getBytes(StandardCharsets.UTF_8)));assertThrows(BusinessException.class,()->new LegacyBankGatewayClient().verifyNotification(body.getBytes(StandardCharsets.UTF_8)));assertEquals(0,calls.get());
 }
}
